from taf.collectors.base import Decorating
from taf.collectors.core import NamedComponentFactory, StartableCollector
from taf.internal.execution.base import ExecutorFactory
from .dcap_starter import DcapStarter


class ClassicalGnbEmilCollector(
        Decorating,
        StartableCollector):
    """Decorating collector for the taf.collectors.dcap collector for emil logs for classical gNB"""


class ClassicalGnbEmilCollectorFactory(
        NamedComponentFactory):
    _product_class = ClassicalGnbEmilCollector

    def __init__(self, **kwargs):
        super(ClassicalGnbEmilCollectorFactory, self).__init__(**kwargs)
        self._dcap_starter = None

    def create(self, configuration, existing_arguments=None):
        collector = super(ClassicalGnbEmilCollectorFactory, self).create(
            configuration=configuration,
            existing_arguments=existing_arguments)
        collector.collector.add_prerequisite(self._dcap_starter)
        return collector

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(ClassicalGnbEmilCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        self._dcap_starter = self._create_dcap_starter(configuration)

    def _create_executor(self, executor_config):
        return ExecutorFactory().create(
            configuration=executor_config,
            existing_arguments={})

    def _create_dcap_starter(self, configuration):
        executor = self._create_executor(executor_config={'type': 'local'})  # todo: support also remote executor
        return DcapStarter(executor=executor)
